/* Citizen Connect Premium Experience. All community actions are browser-local previews. */
(() => {
  'use strict';
  const M=window.CitizenModel, D=window.CitizenData, bible=window.CitizenScripture;
  const store=M.createStore({getItem:key=>localStorage.getItem(key),setItem:(key,value)=>localStorage.setItem(key,value)});
  const $=id=>document.getElementById(id), esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon=(name,cls='')=>`<svg class="${cls}" aria-hidden="true"><use href="#i-${name}"></use></svg>`;
  const labels={read:'Read',share:'Share',memorize:'Memorize',pray:'Pray'}, glyphs={read:'book',share:'chat',memorize:'layers',pray:'pray'};
  const sample={book:'Romans',chapter:8,verses:[26,27,28],reference:'Romans 8:26–28'};
  const S=()=>store.state,E=()=>store.extra;
  let route={screen:'today'}, trail=[], sheet=null, selected=[], toastTimer, focusBeforeSheet, community='all', serveCategory='All', contentCategory='All', query='';
  let draftContext=null, drafts={}, readAll=false;
  const member=id=>D.members.find(m=>m.id===id), opportunity=id=>D.opportunities.find(o=>o.id===id), article=id=>D.content.find(c=>c.id===id);
  const name=()=>String(E().profile.name||'Alex').trim().slice(0,30)||'Alex';
  const initials=()=>name().split(/\s+/).map(s=>s[0]).slice(0,2).join('').toUpperCase();
  const avatar=(id,size='')=>id==='you'?`<span class="avatar initial ${size}" aria-hidden="true">${esc(initials())}</span>`:`<svg class="avatar ${size}" viewBox="${({anna:'383 419 128 128',jess:'633 433 128 128',marcus:'514 446 128 128',taylor:'263 446 128 128'})[id]||'633 433 128 128'}" role="img" aria-label="${esc(member(id)?.name||'Fictional member')}"><image href="assets/member-reference.jpg" width="1024" height="1280"/></svg>`;
  const action=(label,act,variant='',extra='')=>`<button type="button" class="button ${variant}" data-action="${act}" ${extra}>${label}</button>`;
  const navButton=(label,screen,variant='')=>`<button type="button" class="button ${variant}" data-screen="${screen}">${label}</button>`;
  const sectionTop=(title,more='',attrs='')=>`<div class="section-top"><h2>${title}</h2>${more?`<button type="button" class="text-button" ${attrs}>${more}${icon('chevron')}</button>`:''}</div>`;
  const empty=(title,text,button='')=>`<div class="empty-state">${icon('bookmark')}<h3>${title}</h3><p>${text}</p>${button}</div>`;
  const privacy=()=>`<p class="footer-note">Fictional people & opportunities. Your actions stay in this browser.<br>Citizen branding is provisional. No messages or registrations are sent.</p>`;
  const date=id=>S().joined.includes(id)&&E().commitmentDates[id]?new Date(E().commitmentDates[id]):M.eventDate(id,store.clock());
  const when=id=>M.when(date(id),store.clock());
  const shortDate=d=>new Date(d).toLocaleDateString('en-US',{month:'short',day:'numeric'});
  const contextRef=(book,chapter,verses)=>`${book} ${chapter}${verses.length?':'+(verses.length===1?verses[0]:verses.join(', ')):''}`;
  const currentChapter=()=>bible.find(b=>b.book===E().reader.book&&b.chapter===E().reader.chapter)||bible.find(b=>b.book==='Romans'&&b.chapter===8);
  function context(){const ch=currentChapter();if(selected.length)return {book:ch.book,chapter:ch.chapter,verses:[...selected].sort((a,b)=>a-b),reference:contextRef(ch.book,ch.chapter,[...selected].sort((a,b)=>a-b))};if(!readAll&&ch.book==='Romans'&&ch.chapter===8)return {...sample};return {book:ch.book,chapter:ch.chapter,verses:[],reference:`${ch.book} ${ch.chapter}`};}
  const personalRef=id=>E().reflections.find(r=>r.id===id);
  const findRef=id=>personalRef(id)||D.reflections.find(r=>r.id===id);
  const feed=()=>[...E().reflections.filter(r=>r.shared).map(r=>({...r,member:'you'})),...D.reflections];
  const pile=()=>`<div class="avatar-pile">${['anna','jess','marcus'].map(id=>avatar(id,'xs')).join('')}</div>`;
  function peopleStrip(){return `<div><p class="people-caption">Your Wednesday people · fictional demo</p><div class="people-strip" aria-label="Group members"><button type="button" class="person" data-grow="share"><span class="avatar-ring">${avatar('you')}<span class="activity-badge">${icon('edit')}</span></span><span>Your thought</span></button>${D.members.map(m=>`<button type="button" class="person" data-member="${m.id}" aria-label="${m.name}, ${m.activity}"><span class="avatar-ring">${avatar(m.id)}<span class="activity-badge">${icon(m.id==='jess'?'chat':m.id==='marcus'?'heart':m.id==='anna'?'pray':'book')}</span></span><span>${m.first}</span></button>`).join('')}</div></div>`;}
  function ring(){return `<span class="ring-wrap"><svg class="mini-ring" viewBox="0 0 30 30" aria-hidden="true"><circle class="track" cx="15" cy="15" r="12"/><circle class="value" cx="15" cy="15" r="12" style="stroke-dashoffset:${75.4*(1-store.count()/4)}"/></svg><span>${store.count()}/4 today</span></span>`;}
  function rhythm(){const next=store.next();return `<div class="rhythm-grid">${M.practices.map(k=>`<button type="button" class="rhythm-item ${S().done[k]?'done':next===k?'active':''}" data-grow="${k}" aria-label="${labels[k]}${S().done[k]?', completed':''}">${icon(glyphs[k])}<span>${labels[k]}</span><span class="rhythm-mark">${icon('check')}</span></button>`).join('')}</div>`;}
  function gathering(){const d=date('gathering');return `<div class="card gathering-card"><div class="row"><span class="date-tile"><small>${d.toLocaleDateString('en-US',{month:'short'}).toUpperCase()}</small><b>${d.getDate()}</b></span><div class="grow"><h3>A place at the table.</h3><p>${when('gathering')}</p><p>Wednesday Group · North Commons</p></div></div><div class="bottom">${pile()}<button type="button" class="button ${S().rsvp==='going'?'soft':'primary'} compact" data-event="gathering">${S().rsvp==='going'?'✓ You’re going':S().rsvp==='maybe'?'Maybe · Details':'View & RSVP'}${icon('arrow')}</button></div></div>`;}
  function editorial(c,compact=false){return `<button type="button" class="content-preview" data-content="${c.id}" aria-label="Read ${esc(c.title)}"><div class="editorial-art ${c.art}"><span class="eyebrow">${c.kicker}</span><span class="art-word">${c.title}</span><span class="art-number" aria-hidden="true">${c.id==='room-for-spirit'?'08':'↗'}</span></div><div class="preview-copy"><h3>${compact?c.intro:c.title}</h3><p>${c.category} · ${c.minutes} min read · Original demo content</p></div></button>`;}
  function reflectionCard(r){const m=member(r.member),own=r.member==='you',reacted=S().reactions.includes(r.id),comments=E().comments[r.id]||[];return `<article class="card social-card"><div class="feed-author"><button type="button" ${own?'data-screen="profile"':`data-member="${r.member}"`}>${avatar(r.member||'you','sm')}</button><div class="grow"><strong>${own?esc(name()):m?.name||'You'}</strong><small>${own?'Shared by you · local preview':'Wednesday Group · fictional sample'}</small></div>${own?'<span class="pill red">Your post</span>':''}</div><button type="button" class="feed-ref" data-read-context="${r.id}">${icon('book')}${esc(r.reference)}</button><blockquote>${esc(r.text)}</blockquote><div class="social-actions"><button type="button" class="reaction ${reacted?'selected':''}" data-reaction="${r.id}" ${r.id==='jess'?'data-action="react"':''} aria-pressed="${reacted}">${icon('heart')}${reacted?'Encouraged':'Encourage'}</button><button type="button" class="text-button" data-reflection="${r.id}">${icon('chat')}${comments.length?comments.length+' '+(comments.length===1?'comment':'comments'):'Discuss'}</button></div></article>`;}
  function todayView(){const hour=store.clock().getHours(),greeting=hour<12?'Good morning':hour<17?'Good afternoon':'Good evening',next=store.next(),nextCopy={read:['Start with Scripture.','A few quiet minutes in Romans 8.'],share:['Let a thought connect.','Reflect privately or encourage your group.'],memorize:['Carry a little truth.','Practice one verse, one word at a time.'],pray:['Make room for prayer.','For yourself. For your people.']};return `<section class="view today-view"><div class="view-head"><div><p class="eyebrow">${store.clock().toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric'})}</p><h1 class="greeting">${greeting},<br><em>${esc(name())}.</em></h1></div><button type="button" class="icon-button" data-screen="explore" aria-label="Explore Citizen">${icon('compass')}</button></div>${peopleStrip()}
      <div class="card red-card scripture-feature"><div class="feature-top"><span class="eyebrow">A MOMENT IN THE WORD · WEB</span>${icon('book')}</div><h2 class="feature-title">You don’t need<br>perfect words.</h2><p class="feature-verse"><span class="feature-ref">Romans 8:26–28</span>“In the same way, the Spirit also helps our weaknesses…”</p><button type="button" class="button light full" data-grow="read"><span>${S().done.read?'Return to Scripture':'Start reading'}</span>${icon('arrow')}</button>${icon('book','feature-title-mark')}</div>
      <div>${sectionTop('Your daily rhythm')}${rhythm()}<div class="row between space-top"><span class="small muted">Small practices. Real connection.</span>${ring()}</div></div>
      <button type="button" class="card charcoal next-step" data-action="continue"><span class="next-symbol">${icon(next?glyphs[next]:'check')}</span><span class="grow"><span class="eyebrow">${next?'YOUR NEXT STEP':'A MOMENT TO NOTICE'}</span><h3>${next?nextCopy[next][0]:'You made room today.'}</h3><p>${next?nextCopy[next][1]:'Reflect on your rhythm in Progress.'}</p></span>${icon('arrow')}</button>
      <div>${sectionTop('Gather with your people','Happenings','data-screen="happenings"')}${gathering()}</div>
      <div>${sectionTop('This week at Citizen','Explore','data-screen="explore"')}<div class="content-rail">${[D.content[0],D.content[1]].map(c=>editorial(c,true)).join('')}</div></div>
      <div>${sectionTop('From your circle','My Group','data-nav="group"')}${reflectionCard(feed()[0])}</div>
      <div class="card encourage-block">${avatar('taylor','sm')}<div class="grow"><h3>A hello goes a long way.</h3><p>Help Taylor feel welcome this week.</p></div><button type="button" class="icon-button" data-compose="taylor" aria-label="Encourage Taylor">${icon('send')}</button></div>${privacy()}</section>`;}
  function groupView(){return `<section class="view group-view"><div class="group-identity"><span class="eyebrow">YOUR PEOPLE. YOUR PLACE.</span><h1>Wednesday<br>Group.</h1><p>A little more honest. A little more connected. Growing together, one week at a time.</p><div class="row">${pile()}<span>5 people · Fictional demo group</span></div>${icon('people')}</div>${peopleStrip()}${gathering()}
      <div class="discussion-prompt"><span class="eyebrow red">THIS WEEK · ROMANS 8:26–28</span><h3>What if you didn’t have to<br>find the perfect words?</h3><p>Where do you need the Spirit’s help this week?</p><div class="row space-top"><button type="button" class="button dark compact" data-grow="read">Read together ${icon('book')}</button><button type="button" class="text-button" data-content="table-guide">Discussion guide ${icon('arrow')}</button></div></div>
      <div><div class="section-top"><h2>Around the table</h2><button type="button" class="text-button" data-grow="share">Add a reflection ${icon('edit')}</button></div><div class="segmented" aria-label="Group feed filters">${[['all','All activity'],['reflections','Reflections'],['prayers','Prayer']].map(([id,title])=>`<button type="button" data-community="${id}" class="${community===id?'active':''}" aria-pressed="${community===id}">${title}</button>`).join('')}</div></div>
      ${community!=='prayers'?feed().map(reflectionCard).join(''):''}
      ${community!=='reflections'?`<div>${sectionTop('Carry each other','Add prayer','data-grow="pray"')}<div class="stack">${prayerCard({id:'anna',member:'anna',text:member('anna').prayer,shared:true,sample:true})}${E().prayers.filter(p=>p.shared).map(prayerCard).join('')}</div></div>`:''}
      <div>${sectionTop('People to encourage')}<div class="card people-list">${['marcus','taylor'].map(id=>{const m=member(id);return `<div class="person-row"><button class="brand-home" type="button" data-member="${id}" aria-label="About ${m.first}">${avatar(id,'sm')}</button><div class="grow"><strong>${m.name}</strong><small>${m.prompt}</small></div><button type="button" class="icon-button" data-compose="${id}" data-encourage="${id}" aria-label="Encourage ${m.first}">${icon(S().encouraged.includes(id)?'check':'send')}</button></div>`;}).join('')}</div></div>
      <button type="button" class="card opportunity-row" data-event="food"><span class="opportunity-symbol">${icon('heart')}</span><div class="grow"><span class="eyebrow red">SERVE WITH YOUR GROUP</span><h3 class="space-top">Community food drive</h3><p>${when('food')}</p></div>${icon('chevron')}</button>${privacy()}</section>`;}
  function practiceTabs(){return `<div class="practice-tabs" aria-label="Daily practices">${M.practices.map(k=>`<button type="button" class="practice-tab ${route.practice===k?'active':''}" data-grow="${k}" aria-pressed="${route.practice===k}">${labels[k]}${S().done[k]?icon('check'):''}</button>`).join('')}</div>`;}
  function readView(){const practice=route.practice||'read';route.practice=practice;return `<section class="view read-view">${practiceTabs()}${practice==='read'?readerView():practice==='share'?shareView():practice==='memorize'?memoryView():prayView()}${privacy()}</section>`;}
  function readerView(){const ch=currentChapter(),daily=!readAll&&ch.book==='Romans'&&ch.chapter===8,verses=daily?ch.verses.filter(v=>v.number>=26&&v.number<=28):ch.verses;return `<div><span class="eyebrow red">THE WORD, IN YOUR EVERYDAY</span><h1 class="page-title">Room to listen.</h1><p class="subtext">Read slowly. Tap a verse to make it personal.</p></div>
      <div class="reader-tools"><button type="button" class="chapter-button" data-action="chapters" aria-label="Choose Bible book and chapter">${ch.book} ${ch.chapter}<span>WEB</span>${icon('chevron')}</button><div class="font-controls" aria-label="Bible font size"><button type="button" data-font="-1" aria-label="Decrease Scripture font size" ${E().reader.font===18?'disabled':''}>A−</button><button type="button" data-font="1" aria-label="Increase Scripture font size" ${E().reader.font===26?'disabled':''}>A+</button></div></div>
      ${ch.book==='Romans'&&ch.chapter===8?`<div class="segmented"><button type="button" data-reading-mode="passage" class="${daily?'active':''}" aria-pressed="${daily}">Daily passage · 26–28</button><button type="button" data-reading-mode="chapter" class="${!daily?'active':''}" aria-pressed="${!daily}">Full chapter</button></div>`:''}
      <div class="card reader-card"><div class="reader-heading"><span class="eyebrow red">WORLD ENGLISH BIBLE</span><h2>${ch.book} ${ch.chapter}${daily?':26–28':''}</h2><p>Public domain · ${daily?'Today’s group passage':'Offline reading library'}</p></div>${verses.map(v=>{const noteCount=feed().filter(r=>r.book===ch.book&&r.chapter===ch.chapter&&r.verses.includes(v.number)).length;return `<button type="button" id="verse-${v.number}" data-verse="${v.number}" class="verse ${selected.includes(v.number)?'selected':''} ${E().highlights.includes(`${ch.book}:${ch.chapter}:${v.number}`)?'highlighted':''} ${route.focus===v.number?'flash':''}" aria-pressed="${selected.includes(v.number)}" style="font-size:${E().reader.font}px"><sup>${v.number}</sup>${esc(v.text)}${noteCount?`<span class="verse-note" aria-label="${noteCount} community ${noteCount===1?'reflection':'reflections'}">${icon('chat')}${noteCount}</span>`:''}</button>`;}).join('')}
      <div class="chapter-nav"><button type="button" class="button compact" data-chapter-step="-1" ${bible.indexOf(ch)===0?'disabled':''}>← Previous</button><button type="button" class="button compact" data-chapter-step="1" ${bible.indexOf(ch)===bible.length-1?'disabled':''}>Next chapter →</button></div></div>
      ${selected.length?selectionTools():`<div class="reader-privacy">${icon('lock')}<span>Highlights, bookmarks and notes are private on this device. Sharing is always your choice.</span></div>`}
      <button type="button" class="button ${S().done.read?'soft':'primary'} full" data-action="finish-read">${icon(S().done.read?'check':'book')}${S().done.read?'Reading completed today':'Mark reading complete'}</button>
      <div class="row"><button type="button" class="button full" data-action="reflect-passage">Reflect on this passage ${icon('edit')}</button><button type="button" class="icon-button" data-action="bookmark-passage" aria-label="Bookmark this passage">${icon('bookmark')}</button></div>
      <div>${sectionTop('Read it together','View group','data-nav="group"')}<p class="small muted" style="margin-bottom:14px">Community reflections linked to ${ch.book} ${ch.chapter}. All sample activity is fictional.</p>${feed().filter(r=>r.book===ch.book&&r.chapter===ch.chapter&&(!selected.length||r.verses.some(v=>selected.includes(v)))).length?`<div class="stack">${feed().filter(r=>r.book===ch.book&&r.chapter===ch.chapter&&(!selected.length||r.verses.some(v=>selected.includes(v)))).map(reflectionCard).join('')}</div>`:empty('Room for your first thought.','No shared demo reflections on this passage yet.',action('Write privately','reflect-passage','compact dark'))}</div><p class="fine-print">10 complete chapters are available in this demo. <a href="https://ebible.org/web/" target="_blank" rel="noopener noreferrer">World English Bible · public domain</a></p>`;}
  function selectionTools(){return `<div class="selection-tools"><div class="row"><span>${esc(context().reference)}</span><button type="button" class="text-button" data-action="clear-selection">Clear</button></div><div class="actions"><button type="button" data-action="highlight">${icon('sun')}Highlight</button><button type="button" data-action="bookmark-passage">${icon('bookmark')}Save</button><button type="button" data-action="reflect-passage">${icon('edit')}Reflect</button></div></div>`;}
  function shareView(){const ctx=draftContext||sample;return `<div><p class="eyebrow red">SHARE · ONE HONEST THOUGHT</p><h1 class="page-title">Connection<br>starts here.</h1><p class="subtext">Save a private reflection, or make room for a conversation.</p></div><form class="card stack" data-form="reflection"><div class="form-context">${esc(ctx.reference)} · WEB</div><div><label class="field-label" for="reflection-input">What is staying with you?</label><p class="small muted" style="margin-bottom:14px">Where do you need to trust the Spirit’s help today?</p><textarea id="reflection-input" class="note-box" name="reflection" data-draft="reflection" maxlength="2000" required placeholder="An honest thought is a good place to start…">${esc(drafts.reflection||'')}</textarea></div><label class="checkbox-row"><input type="checkbox" name="share" ${drafts.share?'checked':''} data-draft="share"><span><strong>Preview sharing with Wednesday Group</strong><small>Off by default. Adds this reflection to your local demo group feed. Nothing is delivered to real people.</small></span></label><button type="submit" class="button primary full" data-action="save-reflection">${icon('lock')}Save reflection</button><p class="reader-privacy">${icon('lock')}Private on this device unless you explicitly choose the sharing preview.</p></form>
      <button type="button" class="card encourage-block" data-action="encourage">${icon('send')}<div class="grow"><h3>Make someone’s day.</h3><p>Write a personal encouragement preview.</p></div>${icon('chevron')}</button>
      <div>${sectionTop('Your recent thoughts','All saved','data-screen="saved"')}${E().reflections.length?E().reflections.slice(0,2).map(historyCard).join(''):empty('Your story starts with a thought.','Saved reflections will appear here and in Progress.')}</div>`;}
  function memoryView(){const expected=['know','good','love','called','purpose'],bank=['purpose','faith','called','good','know','always','love'];return `<div><p class="eyebrow red">MEMORIZE · CARRY THE WORD</p><h1 class="page-title">A little truth.<br>For the everyday.</h1><p class="subtext">No timer. No score. Just a verse worth carrying.</p></div><div class="card"><span class="pill red">Romans 8:28 · WEB</span><p class="memory-verse">“We <strong>___</strong> that all things work together for <strong>___</strong> for those who <strong>___</strong> God, for those who are <strong>___</strong> according to his <strong>___</strong>.”</p><p class="small muted">Choose the five missing words in order. Tap a filled word to change it.</p><div class="word-slots space-top">${expected.map((w,i)=>`<button type="button" class="word-slot ${S().memoryWords[i]?'filled':''}" data-remove-word="${i}" aria-label="Word ${i+1}, ${S().memoryWords[i]||'empty'}">${esc(S().memoryWords[i]||'____')}</button>`).join('')}</div></div><div class="word-bank">${bank.map(w=>`<button type="button" class="word-chip" data-word="${w}" ${S().memoryWords.includes(w)?'disabled':''}>${w}</button>`).join('')}</div>${S().memoryFeedback?`<div role="status" class="feedback ${S().memoryFeedback==='correct'?'good':''}">${S().memoryFeedback==='correct'?'You’ve got it. Let this truth travel with you today.':'Not quite yet. Change a word, or read the verse again.'}</div>`:''}<button type="button" class="button primary full" data-action="check-memory">${S().done.memorize?'✓ Practice completed · Check again':'Check my words'}</button><div class="row between"><button type="button" class="text-button" data-action="clear-memory">Reset words</button><button type="button" class="text-button" data-action="show-memory">Read the verse ${icon('book')}</button></div>`;}
  function prayerCard(p){const own=!p.sample,who=own?name():member(p.member)?.name,prayed=S().prayed.includes(p.id);return `<article class="card prayer-card"><div class="row">${avatar(own?'you':p.member,'sm')}<div class="grow"><strong>${esc(who)}</strong><small>${own?(p.shared?'Group sharing preview':'Only you · private on this device'):'Fictional group request'}</small></div>${!p.shared?icon('lock'):''}</div><p class="prayer-copy">${esc(p.text)}</p><div class="prayer-actions"><button type="button" class="reaction ${prayed?'selected':''}" data-pray-for="${p.id}" aria-pressed="${prayed}">${icon('pray')}${prayed?'Prayed · Thank you':'I prayed'}</button>${own?`<button type="button" class="text-button" data-remove-prayer="${p.id}">Remove</button>`:'<span class="local-badge">Local acknowledgment</span>'}</div></article>`;}
  function prayView(){return `<div><span class="eyebrow red">PRAY · YOU DON’T NEED PERFECT WORDS</span><h1 class="page-title">What’s on<br>your heart?</h1><p class="subtext">A little space for yourself. A little care for others.</p></div><div class="prayer-privacy">${icon('lock')}<span>Personal prayer intentions stay private on this device. Group sharing is an explicit local preview; no request is sent anywhere.</span></div><form class="card stack" data-form="prayer"><div><label class="field-label" for="prayer-note">A personal prayer intention</label><textarea id="prayer-note" class="note-box" name="prayer" data-draft="prayer" maxlength="1000" placeholder="What do you want to bring to God today?">${esc(drafts.prayer??'')}</textarea></div><label class="checkbox-row"><input type="checkbox" name="sharePrayer" data-draft="sharePrayer" ${drafts.sharePrayer?'checked':''}><span><strong>Preview sharing with my group</strong><small>Optional. Keep others’ personal details private unless they have given permission.</small></span></label><button type="submit" class="button full" data-action="save-prayer">Save prayer intention ${icon('lock')}</button><button type="button" class="button primary full" data-action="finish-pray">${S().done.pray?'✓ Prayer time completed':'Finish prayer time'}</button></form>${E().prayers.length?`<div>${sectionTop('Your intentions')}<div class="stack">${E().prayers.map(prayerCard).join('')}</div></div>`:''}<div>${sectionTop('Pray with your people')}<div class="stack">${['anna','marcus','jess'].map(id=>prayerCard({id,member:id,text:member(id).prayer,shared:true,sample:true})).join('')}</div></div>`;}
  function serveView(){const food=opportunity('food'),joined=S().joined.includes('food'),filtered=D.opportunities.filter(o=>serveCategory==='All'||o.category===serveCategory);return `<section class="view serve-view"><div class="view-head"><div><p class="eyebrow red">FAITH IN MOTION</p><h1 class="page-title large">Good starts<br>with showing up.</h1></div>${icon('heart')}</div><p class="subtext" style="margin-top:-10px">Find your place. Bring your people.</p><div class="card serve-feature"><img class="serve-photo" src="assets/serving.jpg" alt="Two volunteers packing food together, concept photography"><div class="feature-body"><span class="pill red">${icon('people')}With your Wednesday Group</span><h2>${food.title}</h2><p>Pack a box. Meet a neighbor. Spend a morning making something good happen.</p><div class="row">${icon('calendar')}<span>${when('food')} · ${food.duration}</span></div><button type="button" class="button primary full" data-event="food">${joined?'✓ View your commitment':'Explore the food drive'}${icon('arrow')}</button></div></div>
      <div class="category-strip" aria-label="Serving categories">${['All','Community','Hospitality'].map(c=>`<button type="button" class="filter-chip ${serveCategory===c?'active':''}" data-serve-filter="${c}" aria-pressed="${serveCategory===c}">${c}</button>`).join('')}</div><div>${sectionTop('Make a little difference')}<div class="stack">${filtered.map(opportunityCard).join('')}</div></div>
      <div>${sectionTop('Your commitments','Manage','data-action="my-serving"')}${S().joined.length?`<div class="stack">${S().joined.filter(id=>opportunity(id)).map(id=>opportunityCard(opportunity(id),true)).join('')}</div>`:empty('Your next yes is waiting.','When you join a demo opportunity, the details stay right here. No registration is sent.')}</div><button type="button" class="card charcoal next-step" data-screen="happenings"><span class="next-symbol">${icon('calendar')}</span><span class="grow"><span class="eyebrow">LIFE TOGETHER</span><h3>There’s more happening.</h3><p>Gatherings, good conversations, and your next step.</p></span>${icon('arrow')}</button>${privacy()}</section>`;}
  function opportunityCard(o,commitment=false){return `<button type="button" class="card opportunity-row" data-event="${o.id}"><span class="opportunity-symbol">${icon(o.category==='Hospitality'?'people':'heart')}</span><span class="grow"><h3>${o.name}</h3><p>${when(o.id)}</p><p>${commitment?'✓ Your local commitment':o.category+' · '+o.duration}${o.group?' · With your group':''}</p></span>${icon('chevron')}</button>`;}
  function historyCard(r){return `<div class="card history-entry"><div class="row between"><span class="pill ${r.shared?'red':''}">${icon(r.shared?'people':'lock')}${r.shared?'Group preview':'Private'}</span><span>${shortDate(r.createdAt)}</span></div><button type="button" class="feed-ref" data-read-context="${r.id}">${icon('book')}${esc(r.reference)}</button><p>${esc(r.text)}</p><button type="button" class="text-button" data-reflection="${r.id}">Open reflection ${icon('arrow')}</button></div>`;}
  function progressView(){const week=store.weekly(),total=k=>week.filter(d=>d.done[k]).length,readCount=E().readItems.length||Number(S().done.read),shared=E().reflections.filter(r=>r.shared).length;return `<section class="view progress-view"><div><span class="eyebrow red">YOUR GROWTH, YOUR PACE</span><h1 class="page-title large">Keep becoming.</h1><p class="subtext">A life of faith is more than a number. Notice where you’re making room.</p></div><div class="card charcoal week-card"><span class="eyebrow">THIS WEEK’S RHYTHM</span><h2>Small moments.<br>Lasting roots.</h2><p>Each circle holds four practices. This is your actual local activity, without sample totals.</p><div class="week-days">${week.map(d=>{const n=M.practices.filter(k=>d.done[k]).length;return `<div class="week-day ${d.day===S().day?'today':''} ${d.future?'future':''}" aria-label="${d.label}, ${d.future?'upcoming':n+' of 4 completed'}"><span>${d.label.slice(0,1)}</span><div class="day-circle" style="--fraction:${n/4}"><span>${n===4?'✓':d.future?'·':n}</span></div></div>`;}).join('')}</div></div>
      <div class="stat-grid"><div class="card stat-card">${icon('book')}<b>${readCount}</b><strong>Scripture moments</strong><small>Passages you’ve completed</small></div><div class="card stat-card">${icon('edit')}<b>${E().reflections.length}</b><strong>Reflections saved</strong><small>${shared} in your group preview</small></div><div class="card stat-card">${icon('pray')}<b>${E().prayers.length+S().prayed.length}</b><strong>Prayer intentions</strong><small>Saved prayers & acknowledgments</small></div><div class="card stat-card">${icon('heart')}<b>${S().joined.length}</b><strong>Ways you’re serving</strong><small>Your current commitments</small></div></div>
      <div class="card">${sectionTop('A little consistency')}${M.practices.map(k=>`<div class="practice-row">${icon(glyphs[k])}<span class="practice-label">${labels[k]}</span><div class="progress-track" role="progressbar" aria-label="${labels[k]} days this week" aria-valuemin="0" aria-valuemax="7" aria-valuenow="${total(k)}"><div class="progress-fill" style="width:${100*total(k)/7}%"></div></div><span>${total(k)}/7</span></div>`).join('')}<p class="fine-print space-top">No targets to chase. Just a record of the days you showed up.</p></div>
      <div>${sectionTop('Moments that matter')}<div class="card">${[[readCount>0,'book','You made room for the Word.','One honest moment is a meaningful beginning.'],[E().encouragements.length>0||S().encouraged.length>0,'send','You encouraged someone.','A small act of care, beyond your own rhythm.'],[S().joined.length>0,'heart','You put faith into motion.','Making space to serve with your people.']].map(([done,glyph,title,copy])=>`<div class="milestone ${done?'':'pending'}"><span class="milestone-icon">${icon(done?glyph:'lock')}</span><div><h3>${done?title:({'book':'Make room for the Word.','send':'Encourage someone.','heart':'Put faith into motion.'})[glyph]}</h3><p>${done?copy:'Still ahead. Take it at your own pace.'}</p></div></div>`).join('')}</div></div>
      <div>${sectionTop('A moment worth remembering','History','data-screen="saved"')}${E().reflections.length?historyCard(E().reflections[0]):empty('What do you want to remember?','A saved thought can become a reminder of where God met you.',`<button type="button" class="button dark compact" data-grow="share">Write a reflection</button>`)}</div><button type="button" class="card opportunity-row" data-screen="profile"><span class="opportunity-symbol">${icon('user')}</span><span class="grow"><h3>Your space</h3><p>Saved Scripture, preferences & demo controls</p></span>${icon('chevron')}</button>${privacy()}</section>`;}
  function subhead(title,kicker='CITIZEN CONNECT'){return `<div class="subnav"><button type="button" class="icon-button" data-action="back" aria-label="Go back">${icon('arrow')}</button><div><p class="eyebrow">${kicker}</p><h1>${title}</h1></div></div>`;}
  function exploreView(){const filtered=D.content.filter(c=>(contentCategory==='All'||c.category===contentCategory)&&`${c.title} ${c.intro} ${c.reference||''}`.toLowerCase().includes(query.toLowerCase()));return `<section class="view explore-view">${subhead('Explore','SOMETHING FOR YOUR EVERYDAY')}<div><h2 class="page-title large">Keep curious.</h2><p class="subtext">A thought for your day. A guide for your people.</p></div><form data-form="search" class="search-field">${icon('search')}<label class="field-label" for="content-search" hidden>Search demo readings</label><input id="content-search" class="text-input" type="search" name="q" value="${esc(query)}" placeholder="Search readings, guides, Scripture…" aria-label="Search demo readings"><button type="submit" class="button full compact space-top">Search</button></form><div class="category-strip" aria-label="Content categories">${['All','Devotionals','Guides','Stories'].map(c=>`<button type="button" class="filter-chip ${contentCategory===c?'active':''}" data-content-filter="${c}" aria-pressed="${contentCategory===c}">${c}</button>`).join('')}</div><div class="content-list">${filtered.length?filtered.map(c=>editorial(c)).join(''):empty('Try another thought.','No readings match this search. Try “prayer”, “Romans” or choose All.')}</div><p class="fine-print">Original demo articles and guides, written for this prototype. These are not official church messages or recordings.</p>${privacy()}</section>`;}
  function contentView(){const c=article(route.id);if(!c)return notFound();return `<section class="view content-view">${subhead(c.category,'EXPLORE')}<div class="editorial-art ${c.art}" style="border-radius:24px;min-height:210px"><span class="eyebrow">${c.kicker}</span><span class="art-word">${c.title}</span><span class="art-number" aria-hidden="true">08</span></div><div class="row between"><span class="pill">${c.minutes} min read</span><button type="button" class="reaction ${E().savedContent.includes(c.id)?'selected':''}" data-save-content="${c.id}" aria-pressed="${E().savedContent.includes(c.id)}">${icon('bookmark')}${E().savedContent.includes(c.id)?'Saved':'Save reading'}</button></div><h2 class="article-intro">${c.intro}</h2><div class="article-prose">${c.paragraphs.map(p=>`<p>${p}</p>`).join('')}</div><div class="card"><span class="eyebrow red">TAKE IT WITH YOU</span><p class="article-question space-top">${c.question}</p><button type="button" class="button primary full space-top" data-content-reflect="${c.id}">Write a private reflection ${icon('edit')}</button></div><button type="button" class="button full" data-open-passage="daily">Read Romans 8:26–28 ${icon('book')}</button><p class="fine-print">Original demo content. Not official Citizen Church teaching.</p></section>`;}
  function happeningsView(){return `<section class="view happenings-view">${subhead('Happenings','LIFE IS BETTER TOGETHER')}<div><h2 class="page-title large">Make a little<br>room for people.</h2><p class="subtext">Fictional gatherings. Real ways to try the experience.</p></div>${gathering()}<div class="card serve-feature"><img class="serve-photo" src="assets/serving.jpg" alt="Volunteers preparing pantry boxes"><div class="feature-body"><span class="eyebrow red">SERVE WITH YOUR PEOPLE</span><h2>Community food drive</h2><p>${when('food')}</p><button type="button" class="button primary full space-top" data-event="food">View opportunity ${icon('arrow')}</button></div></div><div class="stack">${D.opportunities.slice(1).map(opportunityCard).join('')}</div>${privacy()}</section>`;}
  function eventView(){if(route.id==='gathering')return gatheringDetail();const o=opportunity(route.id);if(!o)return notFound();const joined=S().joined.includes(o.id);return `<section class="view event-view">${subhead('Opportunity','SERVE TOGETHER')}${o.photo?'<img class="serve-photo" style="border-radius:24px" src="assets/serving.jpg" alt="Two volunteers preparing food boxes">':`<div class="editorial-art ${o.id==='meals'?'table':'showup'}" style="border-radius:24px"><span class="eyebrow">${o.category}</span><span class="art-word">${o.title}</span></div>`}<div><span class="pill red">${o.group?'With your Wednesday Group':o.category}</span><h2 class="page-title">${o.name}</h2></div>${joined?`<div class="confirmation" role="status">${icon('check')}<div><strong>You’re on the demo team.</strong><p>Saved to your commitments. This is a local preview; no registration was sent.</p></div></div>`:''}<div class="card meta-list"><div class="meta-line">${icon('calendar')}<div><strong>${when(o.id)}</strong><small>${o.duration} · Fictional opportunity</small></div></div><div class="meta-line">${icon('location')}<div><strong>${o.location}</strong><small>Location is illustrative; do not travel based on this demo.</small></div></div><div class="meta-line">${icon('people')}<div><strong>${o.capacity}</strong><small>Everyone brings something useful.</small></div></div></div><div class="detail-prose"><p>${o.description}</p><h2>What you’ll do</h2><ul class="task-list">${o.tasks.map(t=>`<li>${t}</li>`).join('')}</ul><h2>Good to know</h2><p>${o.requirements}</p><p>${o.bring}</p></div><button type="button" class="button ${joined?'soft':'primary'} full" data-join="${o.id}">${icon(joined?'check':'heart')}${joined?'Leave this demo team':'Join the demo team'}</button><button type="button" class="text-button" data-action="my-serving">View my commitments ${icon('arrow')}</button>${privacy()}</section>`;}
  function gatheringDetail(){return `<section class="view event-view">${subhead('Wednesday Group','NEXT GATHERING')}<div class="group-identity"><span class="eyebrow">A PLACE AT THE TABLE</span><h2 class="page-title" style="color:var(--cream)">Come as<br>you are.</h2><p class="space-top">Scripture, a shared meal, and room for an honest conversation.</p></div><div class="card meta-list"><div class="meta-line">${icon('calendar')}<div><strong>${when('gathering')}</strong><small>Weekly Wednesday gathering · about 90 minutes</small></div></div><div class="meta-line">${icon('location')}<div><strong>North Commons</strong><small>Fictional demo location. No real address is published.</small></div></div><div class="meta-line">${icon('book')}<div><strong>Romans 8:26–28</strong><small>Read, share a thought, pray for each other.</small></div></div></div><div class="card"><h3>Will you be there?</h3><p class="muted space-top">Your RSVP stays in this browser.</p><div class="row space-top">${['going','maybe'].map(value=>`<button type="button" class="button ${S().rsvp===value?'primary':''} full" data-rsvp="${value}" aria-pressed="${S().rsvp===value}">${S().rsvp===value?'✓ ':''}${value==='going'?'I’m going':'Maybe'}</button>`).join('')}</div>${S().rsvp?`<p class="small space-top" role="status">${S().rsvp==='going'?'You’re marked Going.':'You’re marked Maybe.'} Tap again to clear.</p>`:''}</div><div><h3 class="section-top">Your people</h3>${peopleStrip()}</div><div class="card"><h3>This week’s conversation</h3><p class="space-top">Where do you need the Spirit’s help? Bring an honest thought, not a perfect answer.</p><button type="button" class="button dark full space-top" data-content="table-guide">Open discussion guide ${icon('arrow')}</button></div>${privacy()}</section>`;}
  function reflectionView(){const r=findRef(route.id);if(!r)return notFound();const own=!!personalRef(r.id),m=member(r.member),comments=E().comments[r.id]||[];return `<section class="view reflection-view">${subhead('A thought worth sharing',own?'YOUR REFLECTION':'WEDNESDAY GROUP')}<div class="card"><div class="feed-author">${avatar(own?'you':r.member,'sm')}<div><strong>${own?esc(name()):m?.name}</strong><small>${own?(r.shared?'Local group preview':'Private on this device'):'Fictional member reflection'}</small></div></div><button type="button" class="feed-ref" data-read-context="${r.id}">${icon('book')}${esc(r.reference)}</button><p style="font-size:19px;line-height:1.7;overflow-wrap:anywhere">${esc(r.text)}</p>${own?`<label class="checkbox-row space-top"><input type="checkbox" data-share-reflection="${r.id}" ${r.shared?'checked':''}><span><strong>Show in my group preview</strong><small>Your explicit sharing choice. Switching off removes it from the local group feed.</small></span></label><button type="button" class="text-button" data-remove-reflection="${r.id}">Delete my reflection</button>`:`<button type="button" class="reaction ${S().reactions.includes(r.id)?'selected':''} space-top" data-reaction="${r.id}" aria-pressed="${S().reactions.includes(r.id)}">${icon('heart')}${S().reactions.includes(r.id)?'Encouraged':'Encourage'}</button>`}</div><button type="button" class="button dark full" data-read-context="${r.id}">Read in Scripture context ${icon('book')}</button>${r.prompt?`<div class="discussion-prompt"><span class="eyebrow red">LET’S TALK ABOUT IT</span><h3>${r.prompt}</h3></div>`:''}<div class="card"><h2 style="font-size:21px;letter-spacing:-.04em">${own&&!r.shared?'Personal follow-up notes':'Conversation preview'}</h2><p class="small muted space-top">${own&&!r.shared?'Only you can see these notes on this device.':'Comments stay in this browser. Fictional members won’t reply.'}</p>${comments.length?comments.map(c=>`<div class="comment"><div class="row">${avatar('you','xs')}<strong>${esc(name())}</strong><span class="grow"></span><button type="button" class="text-button" data-remove-comment="${c.id}" data-ref-id="${r.id}">Delete</button></div><p>${esc(c.text)}</p></div>`).join(''):'<p class="small muted space-top">Room for an honest thought.</p>'}<form class="stack space-top" data-form="comment" data-ref-id="${r.id}"><label class="field-label" for="comment-input">${own&&!r.shared?'Add a private follow-up':'Add a comment preview'}</label><textarea class="note-box" style="min-height:90px" id="comment-input" name="comment" data-draft="comment" required maxlength="600" placeholder="What does this bring to mind?">${esc(drafts.comment||'')}</textarea><button type="submit" class="button primary full">Save ${own&&!r.shared?'private note':'comment preview'} ${icon('chat')}</button></form></div>${privacy()}</section>`;}
  function savedView(){return `<section class="view saved-view">${subhead('Saved for the everyday','YOUR SPACE')}<div><h2 class="page-title">Keep what matters.</h2><p class="subtext">Your notes and saved passages stay on this device.</p></div><div>${sectionTop('Personal reflections')}${E().reflections.length?`<div class="stack">${E().reflections.map(historyCard).join('')}</div>`:empty('Room for your first reflection.','Start with this week’s passage and see what stays with you.',`<button type="button" class="button dark compact" data-grow="share">Write a thought</button>`)}</div>${E().encouragements.length?`<div>${sectionTop('Care you put into words')}<div class="card">${E().encouragements.map(e=>`<div class="history-entry"><div class="row">${avatar(e.member,'sm')}<strong>For ${esc(member(e.member)?.first||'a friend')}</strong></div><p>${esc(e.text)}</p><span class="fine-print">Local encouragement preview · not delivered · ${shortDate(e.createdAt)}</span></div>`).join('')}</div></div>`:''}<div>${sectionTop('Saved Scripture')}${E().bookmarks.length?`<div class="stack">${E().bookmarks.map((b,i)=>`<div class="card row"><span class="opportunity-symbol">${icon('bookmark')}</span><button type="button" class="text-button grow" style="justify-content:flex-start" data-bookmark-index="${i}">${esc(b.reference)}</button><button type="button" class="icon-button" data-remove-bookmark="${i}" aria-label="Remove bookmark ${esc(b.reference)}">${icon('close')}</button></div>`).join('')}</div>`:empty('A verse to come back to.','Select verses in the reader and tap Save.')}</div><div>${sectionTop('Saved readings')}${E().savedContent.length?`<div class="content-list">${E().savedContent.map(id=>article(id)).filter(Boolean).map(c=>editorial(c)).join('')}</div>`:empty('Something worth a second read.','Save a reading from Explore to find it here.',navButton('Explore readings','explore','dark compact'))}</div>${privacy()}</section>`;}
  function notificationsView(){const items=[{id:'notice-reflection',icon:'chat',title:'A thought from Jess.',text:'“Prayer doesn’t have to be perfect.” Open the sample reflection in its Scripture context.',attr:'data-reflection="jess"'},{id:'notice-gathering',icon:'calendar',title:S().rsvp==='going'?'A place is waiting for you.':'Your next gathering.',text:when('gathering')+' · Wednesday Group. '+(S().rsvp?'RSVP: '+S().rsvp+'.':'Choose your local RSVP.'),attr:'data-event="gathering"'},{id:'notice-serving',icon:'heart',title:S().joined.length?'Your commitments are ready.':'A chance to show up.',text:S().joined.length?`${S().joined.length} local serving ${S().joined.length===1?'commitment':'commitments'}. Check the details before your next step.`:'Explore the sample food drive with your group.',attr:S().joined.length?'data-action="my-serving"':'data-event="food"'}];return `<section class="view notifications-view">${subhead('Your activity','NOTIFICATION PREVIEW')}<p class="small muted">A local activity center, not real push notifications. Tap an update to open its context.</p><div class="stack">${items.map(n=>`<button type="button" class="card notification-item ${E().notificationReads.includes(n.id)?'read':''}" data-notification="${n.id}" ${n.attr}><span class="notice-icon">${icon(n.icon)}</span><span class="grow"><h3>${n.title}</h3><p>${n.text}</p><span class="pill space-top">${E().notificationReads.includes(n.id)?'Opened':'Demo update'}</span></span>${icon('chevron')}</button>`).join('')}</div>${privacy()}</section>`;}
  function profileView(){return `<section class="view profile-view">${subhead('Your space','CONNECTED, AT YOUR PACE')}<div class="card charcoal profile-hero">${avatar('you','lg')}<h2>${esc(name())}</h2><p>Wednesday Group · Local demo profile</p><div class="row" style="justify-content:center;margin-top:15px"><span class="pill dark">${store.count()} of 4 practices today</span></div></div><div class="card">${[['saved','bookmark','Saved Scripture & reflections'],['explore','compass','Explore readings & guides'],['happenings','calendar','Happenings & gatherings']].map(([screen,glyph,title])=>`<button type="button" class="shortcut" data-screen="${screen}">${icon(glyph)}${title}${icon('chevron')}</button>`).join('')}<button type="button" class="shortcut" data-action="my-serving">${icon('heart')}Your serving commitments${icon('chevron')}</button><button type="button" class="shortcut" data-grow="pray">${icon('pray')}Your prayer intentions${icon('chevron')}</button></div><form class="card stack" data-form="preferences"><h3>Make yourself at home.</h3><div><label class="field-label" for="display-name">Demo display name</label><input class="text-input" id="display-name" name="displayName" maxlength="30" required value="${esc(drafts.displayName??name())}" data-draft="displayName" autocomplete="nickname"></div><div><label class="field-label" for="reader-size">Scripture text size</label><select class="select-input" id="reader-size" name="font">${[18,20,23,26].map(n=>`<option value="${n}" ${E().reader.font===n?'selected':''}>${n===18?'Comfortable':n===20?'Standard':n===23?'Large':'Extra large'} · ${n}px</option>`).join('')}</select></div><button type="submit" class="button primary full">Save preferences</button><p class="fine-print">No account is created. This is a name for your local demo only. Motion follows your device’s reduced-motion setting.</p></form><div class="card"><h3>Your privacy matters.</h3><p class="space-top">Notes are private by default. Every shared reflection, comment, RSVP and commitment in this prototype is saved only in this browser. It is never delivered to a real person.</p><p class="fine-print space-top">Browser storage isn’t encrypted account storage. Clearing website data removes these notes. Use fictional content when demonstrating the app.</p></div><div class="card"><span class="eyebrow red">DEMO CONTROLS</span><button type="button" class="shortcut" data-action="replay-intro">${icon('sparkle')}Replay the brand intro${icon('chevron')}</button><button type="button" class="shortcut" data-action="reset-demo">${icon('close')}Reset local demo activity${icon('chevron')}</button></div>${privacy()}</section>`;}
  function notFound(){return `<section class="view">${subhead('Something moved')}${empty('This item isn’t here.','It may have been removed from your local history.',navButton('Back to Today','today','primary'))}</section>`;}
  function nav(){const active=route.tab||(['today','group','read','serve','progress'].includes(route.screen)?route.screen:'today');$('nav').innerHTML=[['today','home','Today'],['group','people','My Group'],['read','book','Read'],['serve','heart','Serve'],['progress','bars','Progress']].map(([id,glyph,label])=>`<button type="button" class="nav-button ${active===id?'active':''}" data-nav="${id}" ${active===id?'aria-current="page"':''}>${icon(glyph)}<span>${label}</span></button>`).join('');$('profile-initials').textContent=initials();document.querySelector('.notification-dot').hidden=E().notificationReads.length>=3;}
  function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
  function render(reset=false){
    store.rollover();const main=$('app-content'),scroll=main.scrollTop,active=document.activeElement,focusId=active?.id;
    const views={today:todayView,group:groupView,read:readView,serve:serveView,progress:progressView,explore:exploreView,content:contentView,happenings:happeningsView,event:eventView,reflection:reflectionView,saved:savedView,notifications:notificationsView,profile:profileView};
    try {main.innerHTML=(store.warning?`<div class="alert" role="status" style="margin-bottom:16px">${esc(store.warning)}</div>`:'')+(views[route.screen]||notFound)();}
    catch(error){console.error('Citizen Connect could not render this view.',error);main.innerHTML=`<section class="view">${subhead('Let’s try that again')}<div class="empty-state"><h3>This view couldn’t open.</h3><p>Your saved activity hasn’t been reset. Return to Today or reload this preview.</p>${navButton('Return to Today','today','primary')}</div></section>`;}
    nav();main.scrollTop=reset?0:scroll;
    if(reset&&!document.documentElement.dataset.intro){const title=main.querySelector('h1');if(title){title.tabIndex=-1;title.focus({preventScroll:true});}}
    else if(focusId&&$(focusId)&&!sheet)$(focusId).focus({preventScroll:true});
    if(sheet)renderSheet();
  }
  function go(next,replace=false){
    closeSheet(false);const primary=['today','group','read','serve','progress'];
    const target=typeof next==='string'?{screen:next}:next;
    target.tab=primary.includes(target.screen)?target.screen:(target.tab||route.tab||route.screen||'today');
    if(target.screen==='read'&&!target.practice)target.practice='read';
    if(!replace)trail.push({...route,scroll:$('app-content').scrollTop});
    route={...target};if(!replace)history.pushState({citizen:true,route},'',location.pathname+location.search);else history.replaceState({citizen:true,route},'',location.pathname+location.search);
    render(true);
    if(route.focus){requestAnimationFrame(()=>{$('verse-'+route.focus)?.scrollIntoView({block:'center',behavior:'auto'});});}
  }
  function back(){if(sheet){closeSheet();return;}if(trail.length)history.back();else go('today',true);}
  function openGrow(practice,ctx){
    if(practice==='read'&&ctx){E().reader.book=ctx.book;E().reader.chapter=ctx.chapter;selected=[];readAll=!(ctx.book==='Romans'&&ctx.chapter===8&&ctx.verses?.every(v=>v>=26&&v<=28));store.save();}
    else if(practice==='read'&&route.screen!=='read'){E().reader.book='Romans';E().reader.chapter=8;readAll=false;selected=[];}
    if(practice==='share'&&ctx)draftContext=ctx;
    go({screen:'read',practice,focus:ctx?.verses?.[0]});
  }
  function openContext(ctx){openGrow('read',ctx);}
  function openSheet(type,id){focusBeforeSheet=document.activeElement;sheet={type,id};renderSheet();}
  function closeSheet(restore=true){if(!sheet)return;sheet=null;$('modal-root').innerHTML='';document.querySelector('.phone-screen').inert=false;if(restore){if(focusBeforeSheet?.isConnected)focusBeforeSheet.focus({preventScroll:true});else $('app-content').focus({preventScroll:true});}}
  function renderSheet(){
    const active=document.activeElement,focusId=active?.id;let title='',body='';
    if(sheet.type==='member'){const m=member(sheet.id);if(!m){closeSheet();return;}title='One of your people';body=`<div class="view"><div class="member-hero">${avatar(m.id,'lg')}<h3>${m.name}</h3><p>${m.role} · Wednesday Group</p></div><p>${m.bio}</p><div class="card"><span class="eyebrow red">RECENT SAMPLE ACTIVITY</span><h3 class="space-top">${m.activity}</h3><p class="space-top">${m.prompt}</p></div><button type="button" class="button primary full" data-compose="${m.id}">Write an encouragement ${icon('send')}</button>${D.reflections.find(r=>r.member===m.id)?`<button type="button" class="button full" data-reflection="${D.reflections.find(r=>r.member===m.id).id}">Read their reflection ${icon('book')}</button>`:''}<p class="fine-print">Fictional demo member. Contact details are not collected or published. Encouragement is a local preview.</p></div>`;}
    if(sheet.type==='encourage'){title='A little encouragement';body=`<div class="stack"><p>Choose a person, then write something thoughtful. No message leaves this device.</p>${D.members.map(m=>`<button type="button" class="card opportunity-row" data-compose="${m.id}">${avatar(m.id,'sm')}<span class="grow"><h3>${m.name}</h3><p>${m.prompt}</p></span>${icon('chevron')}</button>`).join('')}</div>`;}
    if(sheet.type==='compose'){const m=member(sheet.id);title=`Encourage ${m.first}`;body=`<form class="stack" data-form="encourage" data-member-id="${m.id}"><div class="row">${avatar(m.id,'sm')}<div><strong>${m.name}</strong><p class="muted small">Fictional group member</p></div></div><p>${m.prompt}</p><div><label class="field-label" for="encourage-input">Your encouragement</label><textarea id="encourage-input" name="encourage" data-draft="encourage" class="note-box" maxlength="600" required placeholder="I’m glad you’re part of our group…">${esc(drafts.encourage||'')}</textarea></div><button type="submit" class="button primary full">Save encouragement preview ${icon('send')}</button><p class="fine-print">This is not sent. It is saved in your local participation history and completes Share for today.</p></form>`;}
    if(sheet.type==='chapters'){title='A little time in the Word';const ch=currentChapter();body=`<div class="stack"><p class="fine-print">World English Bible · public domain. Ten complete chapters bundled for this offline demo.</p>${[...new Set(bible.map(c=>c.book))].map(book=>`<div><h3 class="field-label">${book}</h3><div class="chapter-options">${bible.filter(c=>c.book===book).map(c=>`<button type="button" data-book="${book}" data-chapter="${c.chapter}" class="${ch.book===book&&ch.chapter===c.chapter?'selected':''}" aria-label="${book} chapter ${c.chapter}" aria-pressed="${ch.book===book&&ch.chapter===c.chapter}">${c.chapter}</button>`).join('')}</div></div>`).join('')}</div>`;}
    if(sheet.type==='my-serving'){title='Your commitments';body=`<div class="stack"><p>Demo commitments are saved on this device only. Joining does not reserve a place at a real event.</p>${S().joined.length?S().joined.filter(id=>opportunity(id)).map(id=>`<div class="card"><h3>${opportunity(id).name}</h3><p class="space-top">${when(id)}</p><div class="row space-top"><button type="button" class="button primary compact" data-event="${id}">View details</button><button type="button" class="button compact" data-join="${id}">Leave team</button></div></div>`).join(''):empty('A place to begin.','Explore a serving opportunity and choose a local commitment.',navButton('Find your place','serve','dark compact'))}</div>`;}
    if(sheet.type==='memory'){title='A verse worth carrying';body=`<div class="stack"><span class="pill red">Romans 8:28 · WEB</span><p class="memory-verse" style="font-size:23px">${esc(bible.find(c=>c.book==='Romans'&&c.chapter===8).verses.find(v=>v.number===28).text)}</p><button type="button" class="button primary full" data-action="close-sheet">Keep practicing</button></div>`;}
    if(sheet.type==='reset'){title='A fresh start?';body=`<div class="stack"><p>This removes all your local demo activity, personal notes, highlights, bookmarks and preferences from this browser. It cannot be undone.</p><button type="button" class="button primary full" data-action="confirm-reset">Reset local demo data</button><button type="button" class="button full" data-action="close-sheet">Keep my activity</button></div>`;}
    if(sheet.type==='remove-reflection'){title='Delete this reflection?';body=`<div class="stack"><p>It will be removed from personal history and the local group preview, along with its comments. This cannot be undone.</p><button type="button" class="button primary full" data-confirm-remove-reflection="${sheet.id}">Delete reflection</button><button type="button" class="button full" data-action="close-sheet">Keep reflection</button></div>`;}
    $('modal-root').innerHTML=`<div class="sheet-backdrop" data-dismiss="sheet"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title" tabindex="-1"><div class="sheet-top"><h2 id="sheet-title">${esc(title)}</h2><button type="button" class="icon-button" data-action="close-sheet" aria-label="Close dialog">${icon('close')}</button></div>${body}</section></div>`;
    document.querySelector('.phone-screen').inert=true;
    if(focusId&&$(focusId)&&$('modal-root').contains($(focusId)))$(focusId).focus({preventScroll:true});
    else $('modal-root').querySelector('[data-action="close-sheet"]').focus({preventScroll:true});
  }
  function changed(message){render();if(message)toast(message);}
  function handleAction(act){
    if(act==='back'){back();return;}
    if(act==='continue'){const next=store.next();next?openGrow(next):go('progress');return;}
    if(act==='finish-read'){store.read(context());changed('Reading completed. Today and Progress are up to date.');return;}
    if(act==='clear-selection'){selected=[];render();return;}
    if(act==='highlight'){store.highlight(context());changed('Highlight updated privately on this device.');return;}
    if(act==='bookmark-passage'){const saved=store.bookmark(context());changed(saved?'Scripture saved to Your space.':'Bookmark removed.');return;}
    if(act==='reflect-passage'){openGrow('share',context());return;}
    if(act==='chapters'||act==='encourage'||act==='my-serving'){openSheet(act);return;}
    if(act==='show-memory'){openSheet('memory');return;}
    if(act==='close-sheet'){closeSheet();return;}
    if(act==='group-details'){go({screen:'event',id:'gathering',tab:'group'});return;}
    if(act==='profile'||act==='notifications'){go(act);return;}
    if(act==='react'){store.toggle('reactions','jess');changed('Encouragement updated in this local preview.');return;}
    if(act==='check-memory'){if(S().memoryWords.length!==5){toast('Choose all five words, then check.');return;}const correct=['know','good','love','called','purpose'].every((w,i)=>S().memoryWords[i]===w);S().memoryFeedback=correct?'correct':'incorrect';if(correct)store.complete('memorize');else store.save();changed(correct?'A verse to carry. Memorize is complete.':'Take another look. There’s no rush.');return;}
    if(act==='clear-memory'){S().memoryWords=[];S().memoryFeedback='';store.save();render();return;}
    if(act==='finish-pray'){const text=$('prayer-note')?.value.trim();if(text){store.pray(text,!!document.querySelector('[name="sharePrayer"]')?.checked);drafts.prayer='';drafts.sharePrayer=false;}store.complete('pray');changed('Prayer time completed. Your intentions stay local.');return;}
    if(act==='reset-demo'){openSheet('reset');return;}
    if(act==='confirm-reset'){store.reset();drafts={};selected=[];draftContext=null;closeSheet(false);go('today',true);toast('A fresh start. Local demo activity was reset.');return;}
    if(act==='replay-intro'){try{sessionStorage.removeItem('citizen-connect-intro-seen-v1');}catch{}location.reload();return;}
  }
  document.addEventListener('click',event=>{
    const b=event.target.closest('button,[data-dismiss]');if(!b)return;
    if(b.dataset.dismiss){if(event.target===b)closeSheet();return;}
    if(b.type==='submit'&&b.form)return;
    try {
      if(b.dataset.notification&&!E().notificationReads.includes(b.dataset.notification)){E().notificationReads.push(b.dataset.notification);store.save();}
      if(b.dataset.nav){go(b.dataset.nav);return;}
      if(b.dataset.screen){go(b.dataset.screen);return;}
      if(b.dataset.grow){openGrow(b.dataset.grow);return;}
      if(b.dataset.content){go({screen:'content',id:b.dataset.content});return;}
      if(b.dataset.event){go({screen:'event',id:b.dataset.event,tab:b.dataset.event==='gathering'?'group':'serve'});return;}
      if(b.dataset.member){openSheet('member',b.dataset.member);return;}
      if(b.dataset.compose){openSheet('compose',b.dataset.compose);return;}
      if(b.dataset.reflection){go({screen:'reflection',id:b.dataset.reflection});return;}
      if(b.dataset.readContext){const r=findRef(b.dataset.readContext);if(r)openContext(r);return;}
      if(b.dataset.openPassage){openContext(sample);return;}
      if(b.dataset.contentReflect){draftContext={...sample,source:article(b.dataset.contentReflect).title};openGrow('share',draftContext);return;}
      if(b.dataset.action){handleAction(b.dataset.action);return;}
      if(b.dataset.reaction){store.toggle('reactions',b.dataset.reaction);changed('Encouragement updated. This is a local preview.');return;}
      if(b.dataset.rsvp){store.rsvp(b.dataset.rsvp);changed(S().rsvp?`RSVP: ${S().rsvp==='going'?'Going':'Maybe'}. Saved on this device.`:'Your RSVP was cleared.');return;}
      if(b.dataset.join){const joined=store.toggle('joined',b.dataset.join);changed(joined?'You joined the demo team. No registration was sent.':'Demo commitment removed.');return;}
      if(b.dataset.prayFor){const prayed=store.toggle('prayed',b.dataset.prayFor);changed(prayed?'Prayer acknowledged locally.':'Prayer acknowledgment removed.');return;}
      if(b.dataset.removePrayer){store.removePrayer(b.dataset.removePrayer);changed('Prayer intention removed.');return;}
      if(b.dataset.removeReflection){openSheet('remove-reflection',b.dataset.removeReflection);return;}
      if(b.dataset.confirmRemoveReflection){store.removeReflection(b.dataset.confirmRemoveReflection);closeSheet(false);go('saved',true);toast('Reflection removed from your local history.');return;}
      if(b.dataset.removeComment){store.removeComment(b.dataset.refId,b.dataset.removeComment);changed('Your comment was removed.');return;}
      if(b.dataset.verse){const n=Number(b.dataset.verse);selected=selected.includes(n)?selected.filter(v=>v!==n):[...selected,n];const pos=$('app-content').scrollTop;render();$('app-content').scrollTop=pos;document.querySelector(`[data-verse="${n}"]`)?.focus({preventScroll:true});return;}
      if(b.dataset.font){const sizes=[18,20,23,26],i=sizes.indexOf(E().reader.font);E().reader.font=sizes[Math.max(0,Math.min(3,i+Number(b.dataset.font)))];store.save();render();return;}
      if(b.dataset.book){E().reader.book=b.dataset.book;E().reader.chapter=Number(b.dataset.chapter);readAll=true;selected=[];store.save();closeSheet(false);if(route.screen!=='read')go({screen:'read',practice:'read'});else render(true);return;}
      if(b.dataset.chapterStep){const next=bible[bible.indexOf(currentChapter())+Number(b.dataset.chapterStep)];if(next){E().reader.book=next.book;E().reader.chapter=next.chapter;readAll=true;selected=[];store.save();render(true);}return;}
      if(b.dataset.readingMode){readAll=b.dataset.readingMode==='chapter';selected=[];render();return;}
      if(b.dataset.word){if(S().memoryWords.length<5){S().memoryWords.push(b.dataset.word);S().memoryFeedback='';store.save();render();}return;}
      if(b.dataset.removeWord!==undefined){S().memoryWords.splice(Number(b.dataset.removeWord),1);S().memoryFeedback='';store.save();render();return;}
      if(b.dataset.community){community=b.dataset.community;render();return;}
      if(b.dataset.serveFilter){serveCategory=b.dataset.serveFilter;render();return;}
      if(b.dataset.contentFilter){query=$('content-search')?.value||query;contentCategory=b.dataset.contentFilter;render();return;}
      if(b.dataset.saveContent){const saved=store.toggleExtra('savedContent',b.dataset.saveContent);changed(saved?'Reading saved to Your space.':'Reading removed from saved.');return;}
      if(b.dataset.bookmarkIndex!==undefined){const bookmark=E().bookmarks[Number(b.dataset.bookmarkIndex)];if(bookmark)openContext(bookmark);return;}
      if(b.dataset.removeBookmark!==undefined){E().bookmarks.splice(Number(b.dataset.removeBookmark),1);store.save();changed('Bookmark removed.');return;}
    } catch(error){toast(error.message||'That action couldn’t be saved. Please try again.');}
  });
  document.addEventListener('input',event=>{const el=event.target;if(el.dataset.draft)drafts[el.dataset.draft]=el.type==='checkbox'?el.checked:el.value;});
  document.addEventListener('change',event=>{const el=event.target;if(el.dataset.shareReflection){store.shareReflection(el.dataset.shareReflection,el.checked);changed(el.checked?'Added to your local group preview. Nothing was sent.':'Reflection is private again. Removed from the group preview.');}if(el.dataset.draft)drafts[el.dataset.draft]=el.type==='checkbox'?el.checked:el.value;});
  document.addEventListener('submit',event=>{
    const form=event.target;if(!form.dataset.form)return;event.preventDefault();
    try {
      const fields=new FormData(form);
      if(form.dataset.form==='reflection'){const text=String(fields.get('reflection')||'').trim();const shared=fields.get('share')==='on';store.reflect(text,draftContext||sample,shared);drafts.reflection='';drafts.share=false;draftContext=null;render();toast(shared?'Saved to your local group preview. Nothing was sent.':'Reflection saved privately. Find it in Your space and Progress.');}
      if(form.dataset.form==='prayer'){store.pray(fields.get('prayer')||'',fields.get('sharePrayer')==='on');drafts.prayer='';drafts.sharePrayer=false;changed('Prayer intention saved with your chosen privacy.');}
      if(form.dataset.form==='comment'){store.comment(form.dataset.refId,fields.get('comment'));drafts.comment='';changed('Your note is saved locally. No message was sent.');}
      if(form.dataset.form==='encourage'){store.encourage(form.dataset.memberId,fields.get('encourage'));drafts.encourage='';closeSheet(false);changed('Encouragement preview saved. Share is complete; nothing was sent.');}
      if(form.dataset.form==='preferences'){const clean=String(fields.get('displayName')||'').trim();if(!clean)throw Error('Add a name for this local demo.');E().profile.name=clean.slice(0,30);const font=Number(fields.get('font'));E().reader.font=[18,20,23,26].includes(font)?font:20;store.save();drafts.displayName=undefined;changed('Your local preferences are saved.');}
      if(form.dataset.form==='search'){query=String(fields.get('q')||'').trim();render();}
    } catch(error){toast(error.message||'Your change couldn’t be saved. Please try again.');}
  });
  document.addEventListener('keydown',event=>{
    if(!sheet)return;
    if(event.key==='Escape'){event.preventDefault();closeSheet();return;}
    if(event.key==='Tab'){const nodes=[...$('modal-root').querySelectorAll('button:not(:disabled),input,textarea,select,a[href],[tabindex="0"]')];const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&(document.activeElement===first||!$('modal-root').contains(document.activeElement))){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
  });
  window.addEventListener('popstate',event=>{closeSheet(false);route=event.state?.citizen?event.state.route:{screen:'today',tab:'today'};const previous=trail.pop();render(true);if(previous?.scroll)$('app-content').scrollTop=previous.scroll;});
  function dayBoundary(){const now=new Date(),next=new Date(now);next.setHours(24,0,0,0);setTimeout(()=>{if(store.rollover()){store.save();render();}dayBoundary();},next-now+50);}
  document.addEventListener('visibilitychange',()=>{if(!document.hidden&&store.rollover()){store.save();render();}});
  history.replaceState({citizen:true,route},'',location.pathname+location.search);
  render(true);
  dayBoundary();
})();
